#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <sys/inotify.h>
#include <fcntl.h>
#include <signal.h>
#include <termios.h>
#include <errno.h>

#define EVENT_SIZE (sizeof(struct inotify_event))
#define BUF_LEN (1024 * (EVENT_SIZE + 16))

int a_flag = 0, c_flag = 0, d_flag = 0, n_flag = 0, p_flag = 0, r_flag = 0, s_flag = 0, x_flag = 0, z_flag = 0;
char **file_names = NULL;
int file_count = 0;
int inotify_fd;
int *watch_descriptors = NULL;

pid_t child_pid = 0;
int pending_event = 0;
int first_execution = 1;

void run_utility(const char *triggered_file);

void handle_signal(int sig) {
    if (child_pid > 0) {
        kill(-child_pid, SIGTERM);
    }
    exit(0);
}

void clear_screen() {
    if (c_flag == 1) {
        printf("\033[2J\033[H");
    } else if (c_flag >= 2) {
        printf("\033[2J\033[3J\033[H");
    }
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "acdnprsxz")) != -1) {
        switch (opt) {
            case 'a': a_flag = 1; break;
            case 'c': c_flag++; break;
            case 'd': d_flag++; break;
            case 'n': n_flag = 1; break;
            case 'p': p_flag = 1; break;
            case 'r': r_flag = 1; break;
            case 's': s_flag = 1; break;
            case 'x': x_flag++; break;
            case 'z': z_flag = 1; break;
            default:
                fprintf(stderr, "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
                return 1;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
        return 1;
    }

    char **utility_args = &argv[optind];

    // Read files from stdin
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, stdin)) != -1) {
        if (read > 0 && line[read - 1] == '\n') {
            line[read - 1] = '\0';
        }
        if (strlen(line) == 0) continue;

        struct stat st;
        if (stat(line, &st) == 0) {
            if (S_ISREG(st.st_mode) || (d_flag && S_ISDIR(st.st_mode))) {
                file_names = realloc(file_names, sizeof(char *) * (file_count + 1));
                file_names[file_count] = strdup(line);
                file_count++;
            }
        }
    }
    free(line);

    if (file_count == 0) {
        fprintf(stderr, "entr: No regular files to watch\n");
        return 1;
    }

    inotify_fd = inotify_init();
    if (inotify_fd < 0) {
        perror("inotify_init");
        return 1;
    }

    watch_descriptors = malloc(sizeof(int) * file_count);
    for (int i = 0; i < file_count; i++) {
        watch_descriptors[i] = inotify_add_watch(inotify_fd, file_names[i], IN_MODIFY | IN_ATTRIB | IN_CLOSE_WRITE | IN_CREATE | IN_DELETE | IN_MOVE);
        if (watch_descriptors[i] < 0) {
            // Some files might not be watchable
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (!p_flag) {
        run_utility(file_names[0]);
        if (z_flag) return 0;
    }

    char buffer[BUF_LEN];
    while (1) {
        int length = read(inotify_fd, buffer, BUF_LEN);
        if (length < 0) {
            if (errno == EINTR) continue;
            break;
        }

        int i = 0;
        while (i < length) {
            struct inotify_event *event = (struct inotify_event *)&buffer[i];
            if (event->mask & (IN_MODIFY | IN_ATTRIB | IN_CLOSE_WRITE | IN_CREATE | IN_DELETE | IN_MOVE)) {
                // Find which file triggered it
                char *triggered_file = NULL;
                for (int j = 0; j < file_count; j++) {
                    if (watch_descriptors[j] == event->wd) {
                        triggered_file = file_names[j];
                        break;
                    }
                }

                if (triggered_file) {
                    if (child_pid > 0 && r_flag) {
                        kill(-child_pid, SIGTERM);
                        waitpid(child_pid, NULL, 0);
                        child_pid = 0;
                    }

                    if (child_pid == 0) {
                        run_utility(triggered_file);
                        if (z_flag) return 0;
                    } else {
                        if (a_flag) {
                            pending_event = 1;
                        }
                    }
                }
            }
            i += EVENT_SIZE + event->len;
        }

        if (pending_event && child_pid == 0) {
            pending_event = 0;
            run_utility(file_names[0]); // Should use the one that triggered it but this is a start
            if (z_flag) return 0;
        }
    }

    return 0;
}

void run_utility(const char *triggered_file) {
    clear_screen();

    child_pid = fork();
    if (child_pid == 0) {
        setpgid(0, 0);

        // Prepare arguments
        // Find how many args there are
        extern char **environ;
        int argc_count = 0;
        while (__reent_unused_argv[argc_count] != NULL) argc_count++; // Wait, this is not right
    }
}
