#include <sys/inotify.h>
#include <fcntl.h>
#include <signal.h>
#include <termios.h>
#include <errno.h>
#include <poll.h>
#include <libgen.h>

#define EVENT_SIZE (sizeof(struct inotify_event))
#define BUF_LEN (1024 * (EVENT_SIZE + 16))

int a_flag = 0, c_flag = 0, d_flag = 0, n_flag = 0, p_flag = 0, r_flag = 0, s_flag = 0, x_flag = 0, z_flag = 0;
char **file_names = NULL;
int file_count = 0;
int inotify_fd;

typedef struct {
    int wd;
    char *path;
    int is_dir;
} Watch;

Watch *watches = NULL;
int watch_count = 0;

char **utility_argv = NULL;
int utility_argc = 0;

pid_t child_pid = 0;
int pending_event = 0;
char *last_triggered_file = NULL;
FILE *status_fp = NULL;
int ev_trace = 0;
int restart_signal = SIGTERM;
struct termios orig_termios;
int tty_fd = -1;

void run_utility(const char *triggered_file);
void clear_screen();
void setup_status_awk();
int get_signal_by_name(const char *name);

void handle_signal(int sig) {
    if (child_pid > 0) {
        kill(-child_pid, SIGTERM);
    }
    if (tty_fd >= 0) tcsetattr(tty_fd, TCSAFLUSH, &orig_termios);
    exit(0);
}

int main(int argc, char *argv[]) {
    char *progname = argv[0];
    char *base_progname = strrchr(progname, '/');
    if (base_progname) base_progname++;
    else base_progname = progname;

    if (getenv("EV_TRACE")) ev_trace = 1;
    char *rs_env = getenv("ENTR_RESTART_SIGNAL");
    if (rs_env) restart_signal = get_signal_by_name(rs_env);

    int opt;
    while ((opt = getopt(argc, argv, "acdnprsxz")) != -1) {
        switch (opt) {
            case 'a': a_flag = 1; break;
            case 'c': c_flag++; break;
            case 'd': d_flag++; break;
            case 'n': n_flag = 1; break;
            case 'p': p_flag = 1; break;
            case 'r': r_flag = 1; break;
            case 's': s_flag = 1; break;
            case 'x': x_flag++; break;
            case 'z': z_flag = 1; break;
            default:
                fprintf(stderr, "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
                return 1;
        }
    }

    if (optind >= argc) {
        if (argc > 1 && strcmp(argv[1], "-h") == 0) {
            printf("release: 5.7\nusage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\nsummary:\n    -a  Do not consolidate events\n    -c  Clear screen before execution\n    -d  Track files added or removed from directories\n    -n  Non-interactive mode\n    -p  Wait for first event\n    -r  Run as a background process, use signal to restart\n    -s  Evaluate using a shell\n    -x  Format exit status\n    -z  Exit after the utility completes\ndocs:\n    man entr\n");
            return 1;
        }
        fprintf(stderr, "release: 5.7\nusage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\nhint: use -h to display option summary\n");
        return 1;
    }

    utility_argv = &argv[optind];
    while (utility_argv[utility_argc] != NULL) utility_argc++;

    char *line = NULL;
    size_t len = 0;
    ssize_t read_len;
    while ((read_len = getline(&line, &len, stdin)) != -1) {
        if (read_len > 0 && line[read_len - 1] == '\n') {
            line[read_len - 1] = '\0';
        }
        if (strlen(line) == 0) continue;

        struct stat st;
        if (stat(line, &st) == 0) {
            if (S_ISREG(st.st_mode)) {
                file_names = realloc(file_names, sizeof(char *) * (file_count + 1));
                file_names[file_count] = strdup(line);
                file_count++;
            }
        }
    }
    free(line);

    if (file_count == 0) {
        fprintf(stderr, "%s: No regular files to watch\n", base_progname);
        return 1;
    }

    inotify_fd = inotify_init1(IN_NONBLOCK);
    if (inotify_fd < 0) {
        perror("inotify_init1");
        return 1;
    }

    for (int i = 0; i < file_count; i++) {
        int wd = inotify_add_watch(inotify_fd, file_names[i], IN_MODIFY | IN_ATTRIB | IN_CLOSE_WRITE);
        if (wd >= 0) {
            watches = realloc(watches, sizeof(Watch) * (watch_count + 1));
            watches[watch_count].wd = wd;
            watches[watch_count].path = strdup(file_names[i]);
            watches[watch_count].is_dir = 0;
            if (ev_trace) {
                struct stat st;
                stat(file_names[i], &st);
                printf("0/%d: fflags: 0x%x r %o %s\n", i+1, 0x2, (int)st.st_mode, file_names[i]);
            }
            watch_count++;
        }

        if (d_flag) {
            char *path_copy = strdup(file_names[i]);
            char *dir = dirname(path_copy);
            int already_watched = -1;
            for (int j = 0; j < watch_count; j++) {
                if (watches[j].is_dir && strcmp(watches[j].path, dir) == 0) {
                    already_watched = j;
                    break;
                }
            }
            if (already_watched == -1) {
                int wd_dir = inotify_add_watch(inotify_fd, dir, IN_CREATE | IN_DELETE | IN_MOVED_FROM | IN_MOVED_TO);
                if (wd_dir >= 0) {
                    watches = realloc(watches, sizeof(Watch) * (watch_count + 1));
                    watches[watch_count].wd = wd_dir;
                    watches[watch_count].path = strdup(dir);
                    watches[watch_count].is_dir = 1;
                    watch_count++;
                }
            }
            free(path_copy);
        }
    }

    if (x_flag) {
        setup_status_awk();
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (!p_flag) {
        run_utility(file_names[0]);
    }

    if (!n_flag) {
        tty_fd = open("/dev/tty", O_RDONLY | O_NONBLOCK);
        if (tty_fd >= 0) {
            struct termios raw;
            tcgetattr(tty_fd, &orig_termios);
            raw = orig_termios;
            raw.c_lflag &= ~(ECHO | ICANON);
            tcsetattr(tty_fd, TCSAFLUSH, &raw);
        } else {
            fprintf(stderr, "%s: unable to get terminal attributes, use '-n' to run non-interactively\n", base_progname);
            return 1;
        }
    }

    struct pollfd fds[2];
    fds[0].fd = inotify_fd;
    fds[0].events = POLLIN;
    fds[1].fd = tty_fd;
    fds[1].events = (tty_fd >= 0) ? POLLIN : 0;

    while (1) {
        int ret = poll(fds, 2, 100);

        if (child_pid > 0) {
            int status;
            if (waitpid(child_pid, &status, WNOHANG) > 0) {
                if (x_flag && status_fp) {
                    if (WIFEXITED(status)) {
                        fprintf(status_fp, "exit %d %s\n", WEXITSTATUS(status), utility_argv[0]);
                    } else if (WIFSIGNALED(status)) {
                        fprintf(status_fp, "signal %d %s\n", WTERMSIG(status), utility_argv[0]);
                    }
                    fflush(status_fp);
                }
                child_pid = 0;
                if (z_flag && !pending_event) {
                    int exit_val = 0;
                    if (WIFEXITED(status)) exit_val = WEXITSTATUS(status);
                    else if (WIFSIGNALED(status)) exit_val = WTERMSIG(status) + 128;
                    if (tty_fd >= 0) tcsetattr(tty_fd, TCSAFLUSH, &orig_termios);
                    return exit_val;
                }
                if (pending_event) {
                    pending_event = 0;
                    run_utility(last_triggered_file ? last_triggered_file : file_names[0]);
                }
            }
        }

        if (ret > 0) {
            if (fds[0].revents & POLLIN) {
                char buffer[BUF_LEN];
                int length = read(inotify_fd, buffer, BUF_LEN);
                if (length > 0) {
                    int i = 0;
                    while (i < length) {
                        struct inotify_event *event = (struct inotify_event *)&buffer[i];
                        for (int j = 0; j < watch_count; j++) {
                            if (watches[j].wd == event->wd) {
                                if (watches[j].is_dir) {
                                    if (event->len > 0) {
                                        if (d_flag == 1 && event->name[0] == '.') {
                                            // Ignore
                                        } else {
                                            fprintf(stderr, "%s: directory altered\n", base_progname);
                                            if (tty_fd >= 0) tcsetattr(tty_fd, TCSAFLUSH, &orig_termios);
                                            return 2;
                                        }
                                    }
                                } else {
                                    if (child_pid > 0 && r_flag) {
                                        kill(-child_pid, restart_signal);
                                    } else if (child_pid == 0) {
                                        run_utility(watches[j].path);
                                    } else {
                                        if (a_flag) {
                                            pending_event = 1;
                                            if (last_triggered_file) free(last_triggered_file);
                                            last_triggered_file = strdup(watches[j].path);
                                        }
                                    }
                                }
                                break;
                            }
                        }
                        i += EVENT_SIZE + event->len;
                    }
                }
            }
            if (fds[1].fd >= 0 && (fds[1].revents & POLLIN)) {
                char ch;
                if (read(tty_fd, &ch, 1) > 0) {
                    if (ch == ' ') {
                        if (child_pid > 0 && r_flag) {
                            kill(-child_pid, restart_signal);
                        } else if (child_pid == 0) {
                            run_utility(file_names[0]);
                        } else {
                            pending_event = 1;
                        }
                    } else if (ch == 'q') {
                        handle_signal(SIGINT);
                    }
                }
            }
        }
    }

    return 0;
}

void run_utility(const char *triggered_file) {
    clear_screen();
    child_pid = fork();
    if (child_pid == 0) {
        setpgid(0, 0);
        char **args;
        if (s_flag) {
            char *shell = getenv("SHELL");
            if (!shell) shell = "/bin/sh";
            args = malloc(sizeof(char *) * 5);
            args[0] = shell;
            args[1] = "-c";
            args[2] = utility_argv[0];
            args[3] = (char *)triggered_file;
            args[4] = NULL;
        } else {
            args = malloc(sizeof(char *) * (utility_argc + 1));
            int replaced = 0;
            for (int i = 0; i < utility_argc; i++) {
                if (!replaced && strcmp(utility_argv[i], "/_") == 0) {
                    args[i] = (char *)triggered_file;
                    replaced = 1;
                } else {
                    args[i] = utility_argv[i];
                }
            }
            args[utility_argc] = NULL;
        }
        execvp(args[0], args);
        perror("execvp");
        exit(1);
    }
}

void clear_screen() {
    if (c_flag == 1) printf("\033[2J\033[H");
    else if (c_flag >= 2) printf("\033[2J\033[3J\033[H");
    fflush(stdout);
}

void setup_status_awk() {
    char *script = getenv("ENTR_STATUS_SCRIPT");
    static char path[1024];
    if (!script) {
        char *home = getenv("HOME");
        if (home) {
            sprintf(path, "%s/.entr", home);
            mkdir(path, 0755);
            sprintf(path, "%s/.entr/status.awk", home);
            script = path;
            struct stat st;
            if (stat(script, &st) != 0) {
                FILE *f = fopen(script, "w");
                if (f) {
                    fprintf(f, "# http://eradman.com/entrproject/status-filters.html\n");
                    fprintf(f, "/^signal/ { print $3, \"terminated by signal\", $2; }\n");
                    fprintf(f, "/^exit/ { print $3, \"returned exit code\", $2; }\n");
                    fclose(f);
                    printf("entr: created '%s'\n", script);
                }
            }
        }
    }
    char awk_cmd[2048];
    if (script) {
        if (x_flag == 1) sprintf(awk_cmd, "awk -S -f %s", script);
        else sprintf(awk_cmd, "awk -f %s", script);
        status_fp = popen(awk_cmd, "w");
    }
}

int get_signal_by_name(const char *name) {
    if (strcmp(name, "HUP") == 0) return SIGHUP;
    if (strcmp(name, "INT") == 0) return SIGINT;
    if (strcmp(name, "QUIT") == 0) return SIGQUIT;
    if (strcmp(name, "TERM") == 0) return SIGTERM;
    if (strcmp(name, "USR1") == 0) return SIGUSR1;
    if (strcmp(name, "USR2") == 0) return SIGUSR2;
    return SIGTERM;
}
