                    if (WIFEXITED(status)) exit_val = WEXITSTATUS(status);
                    else if (WIFSIGNALED(status)) exit_val = WTERMSIG(status) + 128;
                    if (tty_fd >= 0) tcsetattr(tty_fd, TCSAFLUSH, &orig_termios);
                    return exit_val;
                }
                if (pending_event) {
                    pending_event = 0;
                    run_utility(last_triggered_file ? last_triggered_file : file_names[0]);
                }
            }
        }

        if (ret > 0) {
            if (fds[0].revents & POLLIN) {
                char buffer[BUF_LEN];
                int length = read(inotify_fd, buffer, BUF_LEN);
                if (length > 0) {
                    int i = 0;
                    while (i < length) {
                        struct inotify_event *event = (struct inotify_event *)&buffer[i];
                        for (int j = 0; j < watch_count; j++) {
                            if (watches[j].wd == event->wd) {
                                if (watches[j].is_dir) {
                                    if (event->len > 0) {
                                        if (d_flag == 1 && event->name[0] == '.') {
                                            // Ignore
                                        } else {
                                            fprintf(stderr, "%s: directory altered\n", base_progname);
                                            if (tty_fd >= 0) tcsetattr(tty_fd, TCSAFLUSH, &orig_termios);
                                            return 2;
                                        }
                                    }
                                } else {
                                    if (child_pid > 0 && r_flag) {
                                        kill(-child_pid, restart_signal);
                                        pending_event = 1;
                                        if (last_triggered_file) free(last_triggered_file);
                                        last_triggered_file = strdup(watches[j].path);
                                    } else if (child_pid == 0) {
                                        run_utility(watches[j].path);
                                    } else {
                                        if (a_flag) {
                                            pending_event = 1;
                                            if (last_triggered_file) free(last_triggered_file);
                                            last_triggered_file = strdup(watches[j].path);
                                        }
                                    }
                                }
                                break;
                            }
                        }
                        i += EVENT_SIZE + event->len;
                    }
                }
            }
            if (fds[1].fd >= 0 && (fds[1].revents & POLLIN)) {
                char ch;
                if (read(tty_fd, &ch, 1) > 0) {
                    if (ch == ' ') {
                        if (child_pid > 0 && r_flag) {
                            kill(-child_pid, restart_signal);
                            pending_event = 1;
                        } else if (child_pid == 0) {
                            run_utility(file_names[0]);
                        } else {
                            pending_event = 1;
                        }
                    } else if (ch == 'q') {
                        handle_signal(SIGINT);
                    }
                }
            }
        }
    }

    return 0;
}

void run_utility(const char *triggered_file) {
    clear_screen();
    child_pid = fork();
    if (child_pid == 0) {
        setpgid(0, 0);
        setenv("PAGER", "/bin/cat", 0);
        char **args;
        if (s_flag) {
            char *shell = getenv("SHELL");
            if (!shell) shell = "/bin/sh";
            args = malloc(sizeof(char *) * 5);
            args[0] = shell;
            args[1] = "-c";
            args[2] = utility_argv[0];
            args[3] = (char *)triggered_file;
            args[4] = NULL;
        } else {
            args = malloc(sizeof(char *) * (utility_argc + 1));
            int replaced = 0;
            for (int i = 0; i < utility_argc; i++) {
                if (!replaced && strcmp(utility_argv[i], "/_") == 0) {
                    args[i] = (char *)triggered_file;
                    replaced = 1;
                } else {
                    args[i] = utility_argv[i];
                }
            }
            args[utility_argc] = NULL;
        }
        execvp(args[0], args);
        perror("execvp");
        exit(1);
    }
}

void clear_screen() {
    if (c_flag == 1) printf("\033[2J\033[H");
    else if (c_flag >= 2) printf("\033[2J\033[3J\033[H");
    fflush(stdout);
}

void setup_status_awk() {
    char *script = getenv("ENTR_STATUS_SCRIPT");
    static char path[1024];
    if (!script) {
        char *home = getenv("HOME");
        if (home) {
            sprintf(path, "%s/.entr", home);
            mkdir(path, 0755);
            sprintf(path, "%s/.entr/status.awk", home);
            script = path;
            struct stat st;
            if (stat(script, &st) != 0) {
                FILE *f = fopen(script, "w");
                if (f) {
                    fprintf(f, "# http://eradman.com/entrproject/status-filters.html\n");
                    fprintf(f, "/^signal/ { print $3, \"terminated by signal\", $2; }\n");
                    fprintf(f, "/^exit/ { print $3, \"returned exit code\", $2; }\n");
                    fclose(f);
                    printf("entr: created '%s'\n", script);
                }
            }
        }
    }
    char awk_cmd[2048];
    if (script) {
        if (x_flag == 1) sprintf(awk_cmd, "awk -S -f %s", script);
        else sprintf(awk_cmd, "awk -f %s", script);
        status_fp = popen(awk_cmd, "w");
    }
}

int get_signal_by_name(const char *name) {
    if (strcmp(name, "HUP") == 0) return SIGHUP;
    if (strcmp(name, "INT") == 0) return SIGINT;
    if (strcmp(name, "QUIT") == 0) return SIGQUIT;
    if (strcmp(name, "TERM") == 0) return SIGTERM;
    if (strcmp(name, "USR1") == 0) return SIGUSR1;
    if (strcmp(name, "USR2") == 0) return SIGUSR2;
    return SIGTERM;
}
